import type { FilterForm, FilterValue } from 'models/Filters';

export const COMMERCIAL_DRILL_DOWN_DIMENSION_KEYS = [
  'region',
  'channel',
  'brands',
  'sub_brands',
  'pack_type',
  'sku',
] as const;

export type CommercialDrillDownDimensionKey =
  (typeof COMMERCIAL_DRILL_DOWN_DIMENSION_KEYS)[number];

const EMPTY_FILTER_VALUES = new Set(['', 'ALL', 'All']);

export function hasCommercialSpecificFilterValue(value: unknown): boolean {
  if (value === undefined || value === null) return false;
  if (typeof value !== 'string') return true;
  return !EMPTY_FILTER_VALUES.has(value);
}

export function buildCommercialDrillDownClearPatch(
  defaults: FilterForm | undefined,
  keys: readonly CommercialDrillDownDimensionKey[] = COMMERCIAL_DRILL_DOWN_DIMENSION_KEYS,
): Record<string, FilterValue> {
  return keys.reduce<Record<string, FilterValue>>((acc, key) => {
    const defaultValue = defaults?.[key] ?? null;
    const clearValue = hasCommercialSpecificFilterValue(defaultValue)
      ? null
      : defaultValue;

    return { ...acc, [key]: clearValue };
  }, {});
}
